// Extract text content from HTML
const html = $input.first().json.htmlContent;
const url = $input.first().json.productUrl;

// Remove script and style tags
let cleanText = html.replace(/<script[^>]*>([\s\S]*?)<\/script>/gi, '');
cleanText = cleanText.replace(/<style[^>]*>([\s\S]*?)<\/style>/gi, '');

// Remove HTML tags
cleanText = cleanText.replace(/<[^>]+>/g, ' ');

// Clean up whitespace
cleanText = cleanText.replace(/\s+/g, ' ').trim();

// Extract domain name for context
const domain = new URL(url).hostname.replace('www.', '');

return {
  productUrl: url,
  domain: domain,
  rawText: cleanText.substring(0, 50000) // Limit to first 50k chars
};
